@app.route('/custom/<name>')
def custom(name):
    return flask.render_template_string(
        '<h1>Welcome {{person}}</h1>', person=name)

print(app.test_client().get('/custom/Bob').get_data(as_text=True))

def shout(f):
    def wrapper():
        return f().upper() + '!'
    return wrapper

@shout
def hello():
    return 'hello'

print(hello())

